  var cityTowers = [
    { x: -78, z: -48, w: 22, h: 38, d: 18, t: 0 },
    { x: -45, z: -66, w: 26, h: 58, d: 20, t: 1 },
    { x: -8, z: -60, w: 20, h: 44, d: 18, t: 2 },
    { x: 22, z: -64, w: 28, h: 66, d: 22, t: 0 },
    { x: 58, z: -52, w: 24, h: 42, d: 18, t: 1 },
    { x: -88, z: -6, w: 20, h: 30, d: 18, t: 2 },
    { x: 84, z: -18, w: 22, h: 34, d: 20, t: 0 }
  ];

  function buildTowers(tex) {
    var builders = [];
    for (var i = 0; i < cityTowers.length; i++) {
      var t = cityTowers[i];
      var b = new E.Builder();
      var col = C('#ffffff');
      // UV-mapped box: sides sample full texture; roof dark strip
      var x0 = t.x - t.w / 2, x1 = t.x + t.w / 2, y0 = 0, y1 = t.h, z0 = t.z - t.d / 2, z1 = t.z + t.d / 2;
      var s = 1, strip = [[0.97, 0.95], [0.97, 0.97], [0.97, 0.97], [0.97, 0.95]];
      b.quad([x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1], [0, 0, 1], col, [[0, 0], [s, 0], [s, 1], [0, 1]]);
      b.quad([x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [0, 0, -1], col, [[0, 0], [s, 0], [s, 1], [0, 1]]);
      b.quad([x1, y0, z1], [x1, y0, z0], [x1, y1, z0], [x1, y1, z1], [1, 0, 0], col, [[0, 0], [s, 0], [s, 1], [0, 1]]);
      b.quad([x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0], [-1, 0, 0], col, [[0, 0], [s, 0], [s, 1], [0, 1]]);
      b.quad([x0, y1, z1], [x1, y1, z1], [x1, y1, z0], [x0, y1, z0], [0, 1, 0], col, strip);
      builders.push(b.build());
    }
    var meshes = [];
    for (var j = 0; j < builders.length; j++) meshes.push(E.makeTexturedMesh(builders[j]));
    return meshes;
  }

  var screenQuads = {
    code: [], chart: [], sheet: [], chat: [], pres: [], logo: [], sign: []
  };
  function quadUV(b, cx, cy, cz, w, h, hint, uvs) {
    var x0 = cx - w / 2, x1 = cx + w / 2, y0 = cy - h / 2, y1 = cy + h / 2;
    b.quad([x0, y0, cz], [x1, y0, cz], [x1, y1, cz], [x0, y1, cz], hint, C('#ffffff'), uvs || [[0,0],[1,0],[1,1],[0,1]]);
  }

  function buildScreens() {
    // monitors per desk + conference screens + logo + sign
    for (var f = 1; f < FLOORS; f++) {
      var sf = surface(f);
      DESK_COLS.forEach(function (dx, ci) {
        DESK_ROWS.forEach(function (dz, ri) {
          var which = ['code', 'chart', 'sheet', 'chat'][(ci + ri + f) % 4];
          // left monitor
          screenQuads[which].push([dx - 0.52, sf + 1.0, dz - 0.29, 0.74, 0.40]);
          // right monitor
          screenQuads[['chart', 'code', 'chat', 'sheet'][(ci * 3 + ri + f) % 4]].push([dx + 0.52, sf + 1.0, dz - 0.29, 0.74, 0.40]);
        });
      });
      // conference screen
      screenQuads.pres.push([6.9, sf + 1.7, -6.62, 2.6, 1.5]);
    }
    screenQuads.logo.push([-6.6, surface(0) + 1.42, 1.47, 3.1, 1.6]);
    screenQuads.sign.push([0, 3.85, 7.18, 5.4, 1.0]);

    var meshes = {};
    var keys = Object.keys(screenQuads);
    keys.forEach(function (k) {
      var b = new E.Builder();
      screenQuads[k].forEach(function (q) {
        quadUV(b, q[0], q[1], q[2], q[3], q[4], [0, 0, 1]);
      });
      meshes[k] = b.count !== undefined ? E.makeTexturedMesh(b.build()) : null;
    });
    return meshes;
  }

  /* ---------------- sky ---------------- */
  function buildSky() {
    var b = new E.Builder();
    var seg = 24, rings = 12, r = 400;
    for (var j = 0; j < rings; j++) {
      var phi = (j / rings) * Math.PI;
      var y = Math.cos(phi) * r;
      var rad = Math.sin(phi) * r;
      for (var i = 0; i < seg; i++) {
        var th0 = (i / seg) * Math.PI * 2, th1 = ((i + 1) / seg) * Math.PI * 2;
        var a = [Math.cos(th0) * rad, y, Math.sin(th0) * rad];
        var c = [Math.cos(th1) * rad, y, Math.sin(th1) * rad];
        var phi2 = ((j + 1) / rings) * Math.PI;
        var y2 = Math.cos(phi2) * r;
        var rad2 = Math.sin(phi2) * r;
        var d = [Math.cos(th1) * rad2, y2, Math.sin(th1) * rad2];
        var e = [Math.cos(th0) * rad2, y2, Math.sin(th0) * rad2];
        b.quad(a, c, d, e, [Math.cos((th0 + th1) / 2), 0.4, Math.sin((th0 + th1) / 2)], [0, 0, 0]);
      }
    }
    return E.makeMesh(b.build());
  }

