/* ============================================================
   characters.js — workers + pedestrians (dynamic, per-frame)
   1 shared dynamic mesh for all characters (per-vertex colors)
   ============================================================= */
var Characters = (function () {
  'use strict';
  var E = null;
  var W = null;

  var CYCLE = 160;           // seconds per 24h
  var HOURS_PER_SEC = 24 / CYCLE;
  var WALK = 1.55;

  var characters = [];       // {kind, id, floor, desk, chair, x,y,z,yaw, state, path, pathI, speed, phase, colors, ...}
  var pedestrians = [];
  var mesh = null;

  var rng = null;

  var MAX_VERT = 9000;

  function C(hex) {
    var n = parseInt(hex.slice(1), 16);
    return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
  }

  function init(engine, world, seed) {
    E = engine; W = world;
    rng = W.mulberry32(seed || 424242);
    mesh = E.dynMesh(MAX_VERT);
    characters = [];
    pedestrians = [];

    var desks = world.allDesks(); // 4 office floors × 8 desks
    // 6 workers per office floor, assigned to 6 of 8 desks (shuffled)
    var used = {};
    var workers = [];
    var deskIndex = 0;
    var ids = [];
    for (var f = 1; f <= 4; f++) {
      var floorDesks = desks.filter(function (d) { return d.floor === f; });
      // shuffle
      for (var i = floorDesks.length - 1; i > 0; i--) {
        var j = Math.floor(rng() * (i + 1));
        var tmp = floorDesks[i]; floorDesks[i] = floorDesks[j]; floorDesks[j] = tmp;
      }
      var pick = floorDesks.slice(0, 6);
      for (var k = 0; k < pick.length; k++) {
        var d = pick[k];
        workers.push({
          floor: f, desk: d,
          chair: { x: d.x, z: d.z + 0.95, yaw: Math.PI }, // person faces -z (toward desk/monitors)
          yawChair: Math.PI
        });
      }
    }
    // receptionist
    workers.push({ floor: 0, receptionist: true });

    var i2;
    for (i2 = 0; i2 < workers.length; i2++) {
      var w = workers[i2];
      var isReceptionist = !!w.receptionist;
      var stopX = (rng() * 2 - 1) * 11; // sidewalk stop x in [-11, 11]
      var skin = ['#e0b89e', '#caa17e', '#8d6248', '#6b4630', '#f0d0b0', '#b3815c'][Math.floor(rng() * 6)];
      var shirt = isReceptionist ? '#3c5a6b' : ['#4c6a8a', '#5a7a5a', '#8a5a6b', '#6b6a8a', '#8a7a4c', '#4c7a7a', '#7a5a3c', '#5d5d7a'][Math.floor(rng() * 8)];
      var pants = ['#33405c', '#3c4050', '#2f3535', '#463a4a', '#2c3a3a'][Math.floor(rng() * 5)];
      var hair = ['#1e1a16', '#2f241a', '#503722', '#6b4a2e', '#7d7d75', '#8a8a8a', '#2a2018'][Math.floor(rng() * 7)];
      var chair;
      if (isReceptionist) {
        chair = { x: W.RECEPTION.chairX, z: W.RECEPTION.chairZ, yaw: 0 }; // faces entrance (+z)
      } else {
        chair = w.chair;
      }
      characters.push({
        kind: 'worker', id: i2,
        floor: w.floor,
        desk: w.desk || null,
        chair: chair,
        receptionist: isReceptionist,
        stopX: stopX,
        colors: { skin: skin, shirt: shirt, pants: pants, hair: hair },
        x: stopX, y: 0.15, z: 15.9,
        yaw: Math.PI,
        phase: rng() * 6.28,
        state: 'hidden',
        path: [], pathI: 0,
        speed: WALK * (0.9 + rng() * 0.25),
        hidden: true,
        spawnT: 14 + rng() * 18,
        lunchAt: 55 + rng() * 12,
        willLunch: !isReceptionist && rng() < 0.38,
        coffeeAt: 104 + rng() * 8,
        willCoffee: !isReceptionist && rng() < 0.3,
        meetingAt: 82 + (w.floor - 1) * 2.5 + rng() * 5,
        meetingFloor: w.floor,
        meetingDuration: 18,
        leaveAt: 122 + rng() * 12,
        lunchDone: false, coffeeDone: false, meetingDone: false, meetingStart: -1,
        lunchStart: -1, coffeeStart: -1,
        bobPhase: 0
      });
    }

    // pedestrians
    for (i2 = 0; i2 < 3; i2++) {
      var farSide = i2 === 2;
      pedestrians.push({
        kind: 'ped', id: 100 + i2,
        farSide: farSide,
        x: (rng() * 2 - 1) * 34,
        z: farSide ? 29.3 : (i2 === 0 ? 14.25 : 16.15),
        y: 0.16,
        yaw: 0,
        dir: rng() < 0.5 ? 1 : -1,
        speed: 1.1 + rng() * 0.5,
        phase: rng() * 6.28,
        colors: {
          skin: ['#e0b89e', '#caa17e', '#8d6248'][Math.floor(rng() * 3)],
          shirt: ['#7a6b8a', '#5a6a7a', '#8a7a6b'][Math.floor(rng() * 3)],
          pants: '#3c4050',
          hair: ['#1e1a16', '#2f241a', '#6b4a2e'][Math.floor(rng() * 3)]
        }
      });
      pedestrians[i2].yaw = Math.PI / 2 * pedestrians[i2].dir;
    }
    return characters;
  }

  /* ---------- spawn / recycle per cycle ---------- */
  function recycleForCycle() {
    for (var i = 0; i < characters.length; i++) {
      var w = characters[i];
      w.spawnT = 14 + rng() * 20;
      w.lunchAt = 52 + rng() * 12;
      w.willLunch = !w.receptionist && rng() < 0.38;
      w.coffeeAt = 100 + rng() * 10;
      w.willCoffee = !w.receptionist && rng() < 0.3;
      w.meetingAt = 80 + (w.floor - 1) * 2.5 + rng() * 5;
      w.meetingDuration = 18 + rng() * 4;
      w.leaveAt = 120 + rng() * 12;
      w.lunchDone = false; w.coffeeDone = false; w.meetingDone = false;
      w.lunchStart = -1; w.coffeeStart = -1;
      // teleport far away then to stop? teleport to stop directly (far side is night)
      w.hidden = true;
      w.state = 'hidden';
      w.path = []; w.pathI = 0;
      w.x = w.stopX; w.z = 15.9; w.y = 0.15; w.yaw = Math.PI;
    }
  }

  /* ---------- path helpers ---------- */
  function pathToLobby(w) {
    // from outside/street to lobby point (0, -1.6)
    return [{ x: 0, z: 15.9 }, { x: 0, z: 6.95 }, { x: 0, z: -1.6 }];
  }
  function frontCorridor(w) {
    // lobby point → front corridor (0, 5.55)
    return [{ x: 0, z: 5.55 }];
  }
  function deskPath(w, desk) {
    var pts = [];
    if (desk.z > 0) {
      pts = [{ x: 0, z: 5.55 }, { x: desk.x, z: 5.55 }, { x: desk.x, z: desk.chairZ || (desk.z + 0.95) }];
    } else {
      var approachX = desk.x + 1.85;
      pts = [{ x: 0, z: 5.55 }, { x: approachX, z: 5.55 }, { x: approachX, z: -0.55 }, { x: desk.x, z: desk.chairZ || (desk.z + 0.95) }];
    }
    return pts;
  }
  function deskToLobby(w) {
    var d = w.desk;
    if (d.z > 0) {
      return [{ x: w.chair.x, z: 5.55 }, { x: 0, z: 5.55 }, { x: 0, z: -1.6 }];
    }
    var approachX = d.x + 1.85;
    return [{ x: approachX, z: -0.55 }, { x: approachX, z: 5.55 }, { x: 0, z: 5.55 }, { x: 0, z: -1.6 }];
  }
  function confPath(w) {
    // from desk chair to conference chair
    var d = w.desk;
    var cx = w.confChair ? w.confChair.x : 5.65;
    var cz = w.confChair ? w.confChair.z : -5.05;
    var pts = [];
    if (d.z > 0) {
      pts.push({ x: w.chair.x, z: 5.55 });
    } else {
      var approachX = d.x + 1.85;
      pts.push({ x: approachX, z: -0.55 }, { x: approachX, z: 5.55 });
    }
    pts.push({ x: 10.35, z: 5.55 }, { x: 10.35, z: -1.9 }, { x: 5.6, z: -1.9 }, { x: 5.6, z: -4.4 }, { x: cx, z: cz });
    return pts;
  }
  function exitPath(w) {
    // from desk to outside, ending at edge (far side) then teleport
    var pts = [];
    if (w.receptionist) {
      pts = [{ x: -8.3, z: 4.9 }, { x: -8.3, z: 2.0 }, { x: -6.6, z: 1.85 }];
    }
    return pts;
  }

  /* ---------- worker state update ---------- */
  function waypointReached(w, dt) {
    if (!w.path || w.pathI >= w.path.length) return true;
    var target = w.path[w.pathI];
    var dx = target.x - w.x, dz = target.z - w.z;
    var dist = Math.sqrt(dx * dx + dz * dz);
    var step = w.speed * dt;
    if (dist <= step + 0.03) {
      w.x = target.x; w.z = target.z;
      w.pathI++;
      if (w.pathI >= w.path.length) { w.path = []; return true; }
      return false;
    }
    var yawTo = Math.atan2(dx, dz);
    // turn smoothly
    var diff = yawTo - w.yaw;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    w.yaw += diff * Math.min(1, dt * 10);
    w.x += dx / dist * step;
    w.z += dz / dist * step;
    w.phase += dt * w.speed * 5.5;
    return false;
  }

  function setPath(w, pts) {
    if (!pts || pts.length === 0) { w.path = []; return; }
    w.path = pts.slice(); w.pathI = 0;
  }

  function regionOf(w) {
    // inside building?
    return w.x > -10.9 && w.x < 10.9 && w.z > -6.9 && w.z < 6.95;
  }

  function currentSurface(w) {
    if (w.state === 'riding' || w.state === 'boarding' || w.state === 'exiting_car') return w.carY !== undefined ? w.carY : 0.55;
    if (regionOf(w)) {
      return W.surface(w.floor);
    }
    return 0.15;
  }

  function updateWorker(w, dt, t) {
    // t = cycle time in seconds (0..CYCLE)
    var r;

    if (w.hidden) {
      if (t >= w.spawnT) {
        w.hidden = false;
        w.state = 'walk_in';
        setPath(w, pathToLobby(w));
        // for receptionist: enter then reception desk
        if (w.receptionist) {
          w.path = [{ x: 0, z: 15.9 }, { x: 0, z: 6.95 }, { x: 0, z: -1.6 }, { x: 0, z: 5.0 }, { x: -8.3, z: 4.9 }, { x: -8.3, z: 2.0 }, { x: -6.6, z: 1.85 }];
          w.pathI = 0;
        }
      }
      return;
    }

    // smooth y towards region surface
    var targetY = currentSurface(w);
    w.y += (targetY - w.y) * Math.min(1, dt * 7);

    switch (w.state) {
      case 'walk_in':
        r = waypointReached(w, dt);
        if (r) {
          if (w.receptionist) {
            w.state = 'desk'; w.facingYaw = 0;
          } else {
            w.state = 'wait_elev';
          }
        }
        break;
      case 'wait_elev':
        // stand at a wait position to the lobby
        var wp = waitPosition(w);
        w.x += (wp.x - w.x) * Math.min(1, dt * 5);
        w.z += (wp.z - w.z) * Math.min(1, dt * 5);
        w.phase += dt * 0.6;
        // schedule: if lunch comes up while WAITING at elevator — edge cases ignored
        break;
      case 'boarding':
        r = waypointReached(w, dt);
        if (r) { w.state = 'riding'; }
        break;
      case 'riding':
        w.x += (w.carX - w.x) * Math.min(1, dt * 6);
        w.z += (w.carZ - w.z) * Math.min(1, dt * 6);
        w.y = w.carY + 0.12;
        w.yaw = Math.PI; // face back of car (toward interior)
        break;
      case 'exit_car':
        r = waypointReached(w, dt);
        if (r) {
          w.state = 'to_desk';
          setPath(w, deskPath(w, w.desk));
        }
        break;
      case 'to_desk':
        r = waypointReached(w, dt);
        if (r) { w.state = 'desk'; w.facingYaw = w.chair.yaw; w.meetingDone = false; }
        break;
      case 'desk':
        // schedule
        w.x += (w.chair.x - w.x) * Math.min(1, dt * 8);
        w.z += (w.chair.z - w.z) * Math.min(1, dt * 8);
        w.yaw = chairYawFor(w);
        if (w.meetingStart === -1 && !w.meetingDone && w.floor > 0 && t >= w.meetingAt) {
          w.state = 'to_meeting';
          w.meetingStart = t;
          // pick conference chair
          var confChairs = W.conferenceChairs(w.floor);
          var pick = confChairs[(w.id * 7 + w.floor * 3) % confChairs.length];
          w.confChair = pick;
          setPath(w, confPath(w));
        } else if (w.lunchStart === -1 && !w.lunchDone && w.willLunch && t >= w.lunchAt && w.floor > 0) {
          w.state = 'to_lunch';
          w.lunchStart = t;
          setPath(w, lunchRouteOut(w));
        } else if (w.coffeeStart === -1 && !w.coffeeDone && w.willCoffee && t >= w.coffeeAt && w.floor > 0) {
          w.state = 'to_break';
          w.coffeeStart = t;
          setPath(w, lunchRouteOut(w));
        } else if (!w.receptionist && t >= w.leaveAt) {
          w.state = 'walk_out';
          setPath(w, walkOutPath(w));
        } else if (w.receptionist && t >= w.leaveAt) {
          w.state = 'walk_out';
          setPath(w, walkOutPath(w));
        }
        break;
      case 'to_meeting':
        r = waypointReached(w, dt);
        if (r) {
          w.state = 'meeting'; w.meetingDone = true;
        }
        break;
      case 'meeting':
        w.x += (w.confChair.x - w.x) * Math.min(1, dt * 8);
        w.z += (w.confChair.z - w.z) * Math.min(1, dt * 8);
        w.yaw = w.confChair.yaw;
        if (t >= w.meetingStart + w.meetingDuration) {
          w.state = 'to_desk';
          setPath(w, confToDeskPath(w));
        }
        break;
      case 'to_lunch':
      case 'to_break':
        r = waypointReached(w, dt);
        if (r) {
          w.state = 'break';
          w.breakStart = t;
          w.yaw = Math.PI;
        }
        break;
      case 'break':
        w.x += (W.BREAK_PT.x - w.x) * Math.min(1, dt * 8);
        w.z += (W.BREAK_PT.z - w.z) * Math.min(1, dt * 8);
        w.yaw = Math.PI;
        var dur = (w.lunchStart > 0 && t - w.lunchStart < 22) ? 21 : 13;
        var durOK = (w.state === 'break') && t - (w.breakStart > 0 ? w.breakStart : t) >= 0;
        // duration: lunch 21s, coffee 13s
        var isLunch = (w.state === 'break') && (w.lunchStart > 0 && t - w.lunchStart < 22);
        if (isLunch) {
          if (t >= w.lunchStart + 21) { w.lunchDone = true; w.state = 'back_from_break'; setPath(w, breakRouteBack(w)); }
        } else {
          if (w.coffeeStart > 0 && t >= w.coffeeStart + 13) { w.coffeeDone = true; w.state = 'back_from_break'; setPath(w, breakRouteBack(w)); }
        }
