      pts = [{ x: w.chair.x, z: 5.55 }, { x: 0, z: 5.55 }, { x: 0, z: -1.6 }];
    } else {
      var approachX = d.x + 1.85;
      pts = [{ x: approachX, z: -0.55 }, { x: approachX, z: 5.55 }, { x: 0, z: 5.55 }, { x: 0, z: -1.6 }];
    }
