    w.elevatorTargetSet = true;
    return pts;
  }

  function breakRouteBack(w) {
    // break point → lobby (target = worker's floor)
    w.elevatorTarget = w.floor;
    var pts = [{ x: 0, z: -1.6 }];
    return pts;
  }

  function confToDeskPath(w) {
