    var colors = w.colors;
    var walking = (w.state === 'walk_in' || w.state === 'to_desk' || w.state === 'to_meeting' || w.state === 'to_lunch' || w.state === 'to_break' || w.state === 'back_from_break' || w.state === 'back_from_meeting' || w.state === 'walk_out' || w.state === 'exit_car' || w.state === 'boarding');
