      box(-0.29, 1.02, 0.04, 0.11, 0.47, 0.12, shirtCol, armSwingL, 1.0, 0.05);
      box(0.29, 1.02, 0.04, 0.11, 0.47, 0.12, shirtCol, armSwingR, 1.0, 0.05);
