      box(-0.115, 0.40, 0, 0.15, 0.78, 0.18, pantsCol, -legSwing, 0.80, 0);
      box(0.115, 0.40, 0, 0.15, 0.78, 0.18, pantsCol, legSwing, 0.80, 0);
      box(-0.115, 0.05, 0.06, 0.17, 0.10, 0.26, shoeCol, -legSwing, 0.80, 0);
      box(0.115, 0.05, 0.06, 0.17, 0.10, 0.26, shoeCol, legSwing, 0.80, 0);
      var lean = walking ? 0.10 : 0.02;
      box(0, 1.08, 0, 0.46, 0.58, 0.26, shirtCol, lean, 0.82, 0);
