  /* ---------- loop ---------- */
  var lastTs = 0;
  function loop(ts) {
    requestAnimationFrame(loop);
    if (!lastTs) lastTs = ts;
    var dt = (ts - lastTs) / 1000;
    lastTs = ts;
    dt = clamp(dt, 0.001, 0.05);

    camera.idle += dt;
    if (camera.idle > 9 && !dragging) camera.yaw += 0.045 * dt;

    update(dt);
    render();
  }

  window.addEventListener('load', init);

  return { init: init };
})();

