      pts = [{ x: 0, z: 5.55 }, { x: desk.x, z: 5.55 }, { x: desk.x, z: desk.z + 0.95 }];
    } else {
      var approachX = desk.x + 1.85;
      pts = [{ x: 0, z: 5.55 }, { x: approachX, z: 5.55 }, { x: approachX, z: -0.55 }, { x: desk.x, z: desk.z + 0.95 }];
