    var approachX = d.x + 1.85;
    return [{ x: approachX, z: -0.55 }, { x: approachX, z: 5.55 }, { x: 0, z: 5.55 }, { x: 0, z: -1.6 }];
  }

  function confPath(w) {
    var d = w.desk;
    var cx = w.confChair ? w.confChair.x : 5.65;
    var cz = w.confChair ? w.confChair.z : -5.05;
    var pts = [];
    if (d.z > 0) {
      pts.push({ x: w.chair.x, z: 5.55 });
    } else {
